import type { EngineInterface, Register } from 'claude-code'

// メイン会話の最新の思考ブロック。'' のとき非表示。
const THINKING = { plugin: 'thinking-band', key: 'text' } as const

const ACCENT = '#D97757'
const CURSOR = '▍'
// 枠(上下・左右)と見出し、左右の余白とカーソルの分
const CHROME_ROWS = 3
const CHROME_COLUMNS = 6

function show($: EngineInterface, text: string) {
  return $.state.set(THINKING, text)
}

// 端末上の表示幅(全角 2、それ以外 1)。
// ponytail: CJK・全角の主要範囲と Emoji_Presentation だけの近似。結合文字や ZWJ 絵文字はずれるので、困ったら east-asian-width 表に置き換える
function charWidth(ch: string) {
  return /[ᄀ-ᅟ⺀-〾ぁ-㏿㐀-䶿一-鿿ꀀ-꓏가-힣豈-﫿︰-﹏＀-｠￠-￦\u{20000}-\u{3FFFD}\p{Emoji_Presentation}]/u.test(ch) ? 2 : 1
}

function strWidth(s: string) {
  let w = 0
  for (const ch of s) w += charWidth(ch)
  return w
}

// text を幅 width で折り返し、空行を除いた末尾 rows 行を返す。英文は空白で折り返す。
function tailRows(text: string, width: number, rows: number) {
  const out: string[] = []
  for (const para of text.split('\n')) {
    let row = ''
    let w = 0
    for (const ch of para) {
      const cw = charWidth(ch)
      if (w + cw > width) {
        const cut = row.lastIndexOf(' ')
        out.push(cut > 0 ? row.slice(0, cut) : row)
        row = cut > 0 ? row.slice(cut + 1) : ''
        w = strWidth(row)
      }
      row += ch
      w += cw
    }
    out.push(row)
  }
  return out.map(r => r.trim()).filter(r => r !== '').slice(-rows)
}

export const register: Register = (on, options) => {
  const hideOnText = options.hideOn !== 'turn-end'
  const maxLines = Math.max(1, Math.floor(Number(options.maxLines)) || 6)

  // リロード直後や新しいターンに前回の思考を残さない
  on('session.start', async ($, e, next) => {
    await show($, '')
    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    await show($, '')
    return next(e)
  })

  // 観測のみ: チャンクは受け取ったものをそのまま流す
  on('turn.step', async function* ($, e, next) {
    if (e.agentId) return yield* next(e)

    let index = -1
    let thinking = ''
    let hidden = false
    const stream = next(e)
    for await (const c of stream) {
      if (c.kind === 'thinking') {
        if (c.index !== index) {
          index = c.index
          thinking = ''
        }
        thinking += c.text
        if (thinking.trim()) {
          hidden = false
          await show($, thinking)
        }
      } else if (c.kind === 'text' && hideOnText && !hidden) {
        hidden = true
        await show($, '')
      }
      yield c
    }
    // 何も返さないと上位に結果が届かないため、下位の結果をそのまま返す
    return await stream.result
  })

  // 中断(reason: 'aborted')を含むすべてのターン終了で消す。サブエージェントのターン終了は無視する
  on('turn.complete', async ($, e, next) => {
    if (!e.agentId) await show($, '')
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    // 他の mod やエンジンが描いたものは残し、その上に足す
    const below = await next(e)
    const { value: text = '' } = await $.state.get(THINKING)
    // 枠の上下と見出しの 3 行を除いた残りが本文の行数
    const lines = Math.min(maxLines, e.props.maxRows - CHROME_ROWS)
    if (!text || !e.props.isWorking || e.props.hasSurvey || lines <= 0) return below

    const rows = tailRows(text, Math.max(10, e.props.bodyColumns - CHROME_COLUMNS), lines)
    const { Box, Text } = $.ui.resolve(e)

    // 古い行は薄く、最新の行だけ少し明るくしてカーソルを付ける
    return (
      <Box flexDirection="column">
        <Box key="thinking" flexDirection="column" borderStyle="round" borderColor="gray" borderDimColor paddingX={1}>
          <Text color={ACCENT} bold>
            ✻ Thinking
          </Text>
          {rows.map((row, i) =>
            i === rows.length - 1 ? (
              <Text key={`row${i}`} color="gray" italic wrap="truncate-end">
                {row} <Text color={ACCENT}>{CURSOR}</Text>
              </Text>
            ) : (
              <Text key={`row${i}`} color="gray" dimColor italic wrap="truncate-end">
                {row}
              </Text>
            ),
          )}
        </Box>
        {below}
      </Box>
    )
  })
}

