{
  "name": "thinking-band",
  "version": "0.1.0",
  "description": "Shows Claude's latest thinking block above the prompt while a turn runs",
  "author": {
    "name": "orfevre-34",
    "url": "https://github.com/orfevre-34"
  },
  "repository": "https://github.com/orfevre-34/thinking-band",
  "license": "MIT",
  "types": "./types/index.d.ts",
  "userConfig": {
    "hideOn": {
      "type": "string",
      "title": "Hide thinking when",
      "description": "text: when the reply text starts streaming. turn-end: only when the turn ends.",
      "options": [
        "text",
        "turn-end"
      ],
      "default": "text"
    },
    "maxLines": {
      "type": "number",
      "title": "Max lines",
      "description": "Most rows the thinking band takes above the prompt.",
      "default": 6
    }
  }
}

